mapper.select:
SELECT log.log_id, log.operation_type, log.operation_time, log.operation_desc, log.book_id, log.user_id, -- 书籍信息 book.book_id, book.book_name, book.author, book.cover_url, -- 分类信息 category.category_id, category.category_code, category.category_name, -- 用户信息 user.user_id, user.username, user.avatar, user.uid FROM book_operation_log log LEFT JOIN book_info book ON log.book_id = book.book_id LEFT JOIN book_category category ON book.category_id = category.category_id LEFT JOIN sys_user user ON log.user_id = user.user_id WHERE log.operation_type IN (1, 2, 3, 4, 5)
AND ( book.book_name LIKE CONCAT('%', #{param.keyword}, '%') OR book.author LIKE CONCAT('%', #{param.keyword}, '%') OR user.username LIKE CONCAT('%', #{param.keyword}, '%') )
AND category.category_code = #{param.categoryCode}
AND log.operation_type = #{param.operationType}
ORDER BY log.operation_time DESC

SELECT log.log_id, log.operation_type, log.operation_time, log.operation_desc, log.book_id, log.user_id, -- 书籍信息 book.book_id, book.book_name, book.author, book.cover_url, -- 分类信息 category.category_id, category.category_code, category.category_name FROM book_operation_log log LEFT JOIN book_info book ON log.book_id = book.book_id LEFT JOIN book_category category ON book.category_id = category.category_id WHERE log.user_id = #{userId} AND log.operation_type IN (1, 2, 3, 4, 5)
AND ( book.book_name LIKE CONCAT('%', #{param.keyword}, '%') OR book.author LIKE CONCAT('%', #{param.keyword}, '%') OR user.username LIKE CONCAT('%', #{param.keyword}, '%') )
AND category.category_code = #{param.categoryCode}
AND log.operation_type = #{param.operationType}
ORDER BY log.operation_time DESC
